<template>
  <view v-if="visible" class="service-picker" @tap="onMaskTap">
    <view class="service-picker__mask" :class="{ 'service-picker__mask--show': showMask }"></view>
    <view class="service-picker__panel" :class="{ 'service-picker__panel--show': showPanel }" @tap.stop>
      <view class="service-picker__header">
        <view class="service-picker__handle"></view>
        <text class="service-picker__title">联系客服</text>
      </view>
      <scroll-view class="service-picker__list" scroll-y :show-scrollbar="false">
        <view
          v-for="(item, index) in phones"
          :key="index"
          class="service-picker__item"
          @tap="onSelect(item)"
        >
          <view class="service-picker__icon">
            <text class="service-picker__icon-text">☎</text>
          </view>
          <view class="service-picker__info">
            <text class="service-picker__name">{{ item.name || '客服热线' }}</text>
            <text class="service-picker__phone">{{ item.phone }}</text>
          </view>
          <view class="service-picker__arrow">
            <text class="service-picker__arrow-text">›</text>
          </view>
        </view>
      </scroll-view>
      <view class="service-picker__footer">
        <view class="service-picker__cancel" @tap="close">
          <text class="service-picker__cancel-text">取消</text>
        </view>
      </view>
    </view>
  </view>
</template>

<script>
export default {
  name: 'ServicePicker',
  props: {
    visible: {
      type: Boolean,
      default: false
    },
    phones: {
      type: Array,
      default: () => []
    }
  },
  data() {
    return {
      showMask: false,
      showPanel: false,
      isVisible: false
    }
  },
  watch: {
    visible: {
      handler(newVal) {
        if (newVal && !this.isVisible) {
          this.isVisible = true
          this.open()
        } else if (!newVal && this.isVisible) {
          this.isVisible = false
          this.close()
        }
      }
    }
  },
  methods: {
    open() {
      this.$nextTick(() => {
        this.showMask = true
        setTimeout(() => {
          this.showPanel = true
        }, 20)
      })
    },
    close() {
      this.showPanel = false
      setTimeout(() => {
        this.showMask = false
        this.$emit('update:visible', false)
        this.$emit('close')
      }, 280)
    },
    onMaskTap() {
      this.close()
    },
    onSelect(item) {
      this.$emit('select', item)
      this.close()
    }
  }
}
</script>

